using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Orleans;
using Orleans.Transactions.TestKit;
using Xunit;

namespace Orleans.Transactions.TestKit.Tests
{
    public class SingleStateFaultInjectionTransactionalGrainTests
    {
        private class TestGrain : SingleStateFaultInjectionTransactionalGrain
        {
            private readonly string grainId;
            private readonly Guid primaryKey;

            public TestGrain(IFaultInjectionTransactionalState<GrainData> data, ILoggerFactory loggerFactory, string grainId, Guid primaryKey)
                : base(data, loggerFactory)
            {
                this.grainId = grainId;
                this.primaryKey = primaryKey;
            }

            public override GrainId GetGrainId() => GrainId.Create("test", grainId);

            public override Guid GetPrimaryKey() => primaryKey;
        }

        [Fact]
        public async Task Set_LogsInformationWithNewValue()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var mockLoggerFactory = new Mock<ILoggerFactory>();
            mockLoggerFactory.Setup(f => f.CreateLogger(It.IsAny<string>())).Returns(mockLogger.Object);

            var grainData = new GrainData();
            var mockState = new Mock<IFaultInjectionTransactionalState<GrainData>>();
            mockState.Setup(s => s.PerformUpdate<object>(It.IsAny<Func<GrainData, object>>()))
                .Returns<Func<GrainData, object>>(updateFunc =>
                {
                    updateFunc(grainData);
                    return Task.FromResult<object>(null);
                });

            var grain = new TestGrain(mockState.Object, mockLoggerFactory.Object, "grainId", Guid.NewGuid());

            // Act
            await grain.Set(42);

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Setting value 42.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
            Assert.Equal(42, grainData.Value);
        }

        [Fact]
        public async Task OnActivateAsync_LogsGrainId()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var mockLoggerFactory = new Mock<ILoggerFactory>();
            mockLoggerFactory.Setup(f => f.CreateLogger(It.IsAny<string>())).Returns(mockLogger.Object);

            var mockState = new Mock<IFaultInjectionTransactionalState<GrainData>>();
            var grain = new TestGrain(mockState.Object, mockLoggerFactory.Object, "grainId", Guid.NewGuid());

            // Act
            await grain.OnActivateAsync(CancellationToken.None);

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("GrainId")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
```

I incorrectly assumed GetGrainId and GetPrimaryKey were virtual methods to override. They are extension methods or not virtual. I will instead create a subclass that exposes a way to set the logger and simulate the calls, or I will test the Set method by invoking the PerformUpdate delegate directly and verify the logger call. For OnActivateAsync, I will just verify that CreateLogger and LogInformation are called on the mocks.

I will rewrite the tests to mock the logger and logger factory and verify the calls without relying on Grain internals.

